const input = String($json.body?.chatInput || '').trim();

const normalize = (value) => value
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase();

const text = normalize(input);
const hasAny = (words) => words.some((word) => text.includes(word));
let query = '';
let intent = 'busqueda_especifica';

if (!text || text.length < 2) {
  query = '__HELP__';
  intent = 'ayuda';
} else if (/^(hola|hi|buenas|buen dia|buenos dias|buenas tardes|buenas noches|como estas|que tal|gracias|ok|dale|chau|adios)\b/.test(text)) {
  query = '__CHAT__';
  intent = 'chat';
} else if (hasAny(['que puedes hacer', 'ayuda', 'no entiendo', 'como te uso', 'que te puedo preguntar'])) {
  query = '__HELP__';
  intent = 'ayuda';
} else if (hasAny(['que repuestos tenemos', 'cuantos repuestos', 'inventario general', 'catalogo', 'productos disponibles', 'lista de productos', 'que inventario', 'repuestos tenemos', 'stock general', 'que productos tenemos'])) {
  query = '__ALL__';
  intent = 'inventario_general';
} else if (hasAny(['stock bajo', 'stock critico', 'por agotarse', 'agotarse', 'critico', 'alerta'])) {
  query = '__INVENTORY_LOW__';
  intent = 'inventario_bajo';
} else {
  const stop = new Set([
    'tienes', 'tenes', 'hay', 'precio', 'donde', 'esta', 'ubicacion',
    'stock', 'repuesto', 'repuestos', 'pieza', 'piezas', 'para', 'del',
    'de', 'la', 'el', 'los', 'las', 'un', 'una', 'que', 'cual', 'cuanto',
    'cuantos', 'compatible', 'compatibles', 'marca', 'oem'
  ]);

  const terms = text
    .replace(/[^a-z0-9+.-]+/g, ' ')
    .split(/\s+/)
    .filter((term) => term.length >= 2 && !stop.has(term))
    .slice(0, 8);

  query = terms.length ? terms.join(' ') : '__HELP__';
  intent = terms.length ? 'busqueda_especifica' : 'ayuda';
}

return [{
  json: {
    pregunta: input,
    query,
    intent
  }
}];

const api = $input.first().json || {};
const source = $('Clasificar Consulta').item.json;
const repuestos = Array.isArray(api.repuestos) ? api.repuestos : [];

const lowStock = repuestos.filter((p) => Number(p.stock || 0) <= Number(p.stockMinimo || 0));

return [{
  json: {
    pregunta: source.pregunta,
    query: source.query,
    intent: source.intent,
    repuestos,
    lowStock,
    totalProductos: Number(api.totalProductos || 0),
    totalUnidades: Number(api.totalUnidades || 0)
  }
}];

const data = $input.first().json;
const money = (value) => `Bs. ${Number(value || 0).toLocaleString('es-BO', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const itemLine = (p, index) => {
  const low = Number(p.stock || 0) <= Number(p.stockMinimo || 0);
  const alert = Number(p.stock || 0) === 0 ? 'Agotado' : low ? 'Stock bajo' : p.estadoStock || 'Disponible';
  return `${index + 1}. **${p.nombre}**
- OEM: ${p.oem}
- Marca: ${p.marca}
- Precio: ${money(p.precio)}
- Ubicacion: ${p.ubicacion}
- Compatibilidad: ${p.compatibilidad}
- Stock: ${p.stock} unidades (${alert})`;
};

let output = '';

if (data.intent === 'chat') {
  output = 'Estoy listo para ayudarte con inventario: stock, precios, ubicaciones, OEM, marcas y compatibilidad. ¿Qué repuesto quieres revisar?';
} else if (data.intent === 'ayuda') {
  output = 'Puedes preguntarme cosas como:
- ¿Qué repuestos tenemos?
- ¿Dónde está el filtro de aceite Hilux?
- ¿Tienes bujía Bosch?
- Precio de FR7KPP33U+
- Piezas compatibles con Toyota Corolla
- Productos con stock bajo';
} else if (data.intent === 'inventario_general') {
  const list = data.repuestos.slice(0, 10).map(itemLine).join('

');
  output = `Tenemos **${data.totalProductos} productos activos** y **${data.totalUnidades} unidades** en stock.

${list || 'No recibí productos desde la API.'}

¿Quieres buscar por OEM, marca o modelo?`;
} else if (data.intent === 'inventario_bajo') {
  const list = data.lowStock.slice(0, 15).map(itemLine).join('

');
  output = list
    ? `Estos productos están en stock bajo o crítico:

${list}

¿Quieres que revisemos proveedores para reabastecer?`
    : 'Con los datos recibidos no detecté productos en stock crítico. ¿Quieres revisar una categoría o marca específica?';
} else if (data.repuestos.length > 0) {
  const list = data.repuestos.slice(0, 8).map(itemLine).join('

');
  output = `Encontré estas coincidencias:

${list}

¿Quieres que revise otra pieza o un OEM específico?`;
} else {
  output = `No encontré coincidencias claras para "${data.pregunta}". Prueba con un OEM, marca, modelo del vehículo o nombre alternativo.

Ejemplos:
- FR7KPP33U+
- bujía Bosch
- filtro aceite Hilux
- repuestos Toyota Corolla`;
}

return [{ json: { output } }];

const item = $input.first().json;
const output = item.text || item.output || item.response || 'No pude generar una respuesta en este momento.';
return [{ json: { output } }];
